const a={ui:{fig:"Fig. 1",title:"Fondo ripiegato all'interno",svgLabel:"Un disegno isometrico di come si fa un fondo ripiegato all'interno: la piega centrale, due pieghe cucite a 6 cm da essa, il fondo ripiegato dentro, le cuciture laterali che lo prendono e la borsa rivoltata.",prev:"Passo precedente",dot:(e,i)=>e?`Passo ${e}: ${i}`:i,start:"Passo passo →",next:"Avanti →",overview:"Panoramica",stepOf:(e,i)=>`Passo ${e} di ${i}`,machine:e=>`Macchina: ${e.toLowerCase()}`,inThisStep:"In questo passo",takeApart:"Rimetti in piedi",putTogether:"Mostra il fondo",replay:"↻ Ripeti",parts:"Parti",allSteps:"Istruzioni passo passo",endView:"SEZIONE"},stitches:{straight:"Punto dritto"},labels:{foldPress:"piega a metà e stira",centreCrease:"piega centrale",cm6:"6 cm",rightSides:"dritto contro dritto",stitchFold:"cuci a filo della piega",bottom12:"fondo 12 cm",liftEnds:"solleva le estremità lungo le pieghe cucite",foldsIn:"il fondo rientra",centreInside:"centro 6 cm dentro",seam05:"cuci a 0,5 cm",layers4:"4 strati qui",turnOut:"rivolta sul dritto",openUp:"aprila",base12:"base 12 cm",cornersForm:"gli angoli si formano da soli"},steps:[{title:"Il fondo ripiegato all'interno",text:"Il fondo della tote bag, con la borsa capovolta: una base piatta di 12 cm tra due pieghe cucite, e angoli che si formano da soli, senza cuciture agli angoli. Tocca la borsa per rimetterla in piedi."},{title:"Segna il centro e misura",text:"Piega il pezzo a metà per il largo, stira la piega e riaprilo. Misura 6 cm dalla piega verso ciascuna estremità e traccia una linea di traverso.",details:["La borsa si taglia in un solo pezzo, piegato a metà per il largo: il fondo è al centro del pezzo.","Piegalo a metà per il largo e stira la piega. Riaprilo: la piega è il centro del fondo.","Misura 6 cm dalla piega verso ciascuna estremità e traccia con la penna evanescente una linea su tutta la larghezza del pezzo."]},{title:"Cuci una piega su ogni linea",text:"Piega lungo la prima linea, dritto contro dritto, e cuci a filo della piega. Riapri e fai lo stesso sulla seconda linea: due pieghe cucite, a 12 cm l'una dall'altra.",details:["Piega il pezzo lungo la prima linea, dritto contro dritto, e cuci a filo della piega per tutta la larghezza. Riaprilo.","Piega e cuci allo stesso modo lungo la seconda linea.","Le due pieghe cucite, a 12 cm l'una dall'altra, sono i bordi del fondo; la piega centrale ne segna la metà. Nel passo successivo il pezzo si piega proprio su queste pieghe."]},{title:"Ripiega il fondo all'interno",text:"Solleva entrambe le estremità piegando lungo le pieghe cucite e uniscile: il fondo rientra e la piega centrale va 6 cm all'interno. Stendi il pezzo in piano.",details:["Appoggia il pezzo con il dritto verso l'alto e solleva entrambe le estremità, così che si curvi sulle due pieghe cucite.","Unisci le estremità. Il fondo di 12 cm si ripiega su se stesso e la piega centrale va all'interno, 6 cm in su tra gli strati — come il fondo di un sacchetto di carta.","Stendilo in piano, dritto contro dritto. Ora le pieghe cucite sono il bordo inferiore."]},{title:"Cuci i lati",text:"Tieni il fondo ripiegato all'interno e cuci entrambi i lati a 0,5 cm — attraverso tutti gli strati, quattro in basso.",details:["Fissa i lati con le clip, così il fondo ripiegato resta al suo posto.","Cuci entrambe le cuciture laterali a 0,5 cm dal bordo, per tutta la lunghezza. In basso la cucitura passa attraverso quattro strati: il davanti, le due metà del fondo ripiegato e il dietro. Lascia aperto il lato superiore.","Nella tote bag la fodera si cuce allo stesso modo: solo che in una delle sue cuciture laterali si lascia un'apertura, per rivoltare poi la borsa."]},{title:"Rivoltala sul dritto",text:"Rivolta la borsa sul dritto e aprila: il fondo si distende in una base piatta di 12 cm e gli angoli si formano da soli.",details:["Rivolta la borsa sul dritto dall'apertura in alto.","Aprila e spingi fuori il fondo. Il fondo ripiegato si distende in una base piatta di 12 cm e, dove le cuciture laterali l'hanno fermato, si formano da soli angoli precisi — senza cuciture in più per gli angoli."]}],legend:[{title:"Base",text:"piatta, larga 12 cm: il fondo tra le due pieghe cucite"},{title:"Pieghe cucite",text:"una piega cucita a filo del bordo, a 6 cm dalla piega centrale, una per lato · i lati lunghi della base"},{title:"Piega centrale",text:"il centro del fondo · ripiegata 6 cm all'interno prima di cucire i lati"},{title:"Cuciture laterali",text:"0,5 cm, cucite con il fondo ripiegato · quattro strati in basso"},{title:"Angoli",text:"si formano da soli dove le cuciture laterali hanno preso il fondo ripiegato · senza cuciture agli angoli"}]};export{a as default};
